internal object DuaEsDraft1 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_muawwidhat" to DuaText("Los Tres Quls (Mu'awwidhat)", "(Surah al-Ikhlas) Di: Él es Allah, el Único. Allah, el Autosuficiente. Ni engendra ni nace. Y no hay nadie comparable a Él.\n\n(Surah al-Falaq) Di: Busco refugio en el Señor del amanecer, del mal de lo que Él ha creado, del mal de la oscuridad cuando se asienta, del mal de aquellos que soplan nudos y del mal del envidioso cuando envidia.\n\n(Surah an-Nas) Di: Busco refugio en el Señor de la humanidad, el Rey de la humanidad, el Dios de la humanidad, del mal del susurrador que se retira, que susurra en los corazones de la humanidad, de entre los genios y la humanidad.", "Las tres suras tres veces por la mañana y por la noche, y antes de dormir, soplar en las manos y pasarlas por el cuerpo.", "Recitarlos tres veces por la mañana y por la tarde es suficiente contra todo."),
        "dua_sabr" to DuaText("Por paciencia y firmeza", "Señor nuestro, derrama sobre nosotros paciencia, haz firmes nuestros pies y ayúdanos contra los incrédulos.", "En tiempos de dificultad y confrontación.", "La dua del ejército de Talut."),
        "dua_rabbana_innana_amanna" to DuaText("Perdón y protección contra el fuego", "Señor nuestro, hemos creído, perdónanos nuestros pecados y protégenos del castigo del Fuego.", "Una dua coránica.", "Un dua mencionado entre las cualidades de los temerosos de Dios."),
        "dua_rabbana_hab_lana_rahmah" to DuaText("Orientación en nuestros asuntos (Ashab al-Kahf)", "Señor nuestro, concédenos misericordia de Ti mismo y prepáranos la dirección correcta en nuestro asunto.", "La dua del Pueblo de la Caverna.", "Orientación en decisiones y situaciones difíciles."),
        "dua_musa_faqir" to DuaText("Dua de Musa (AS) para provisión", "Mi Señor, realmente necesito cualquier bien que me envíes.", "Buscando provisión y bien: la dua de Musa (AS) en Madyan.", "Después de esta dua, Allah le concedió a Musa (AS) un hogar, trabajo y una esposa."),
        "dua_ayyub" to DuaText("Dua de Ayyub (AS) en enfermedad", "(Mi Señor), el mal me ha tocado, y Tú eres el Misericordioso de los misericordiosos.", "En la enfermedad y el sufrimiento.", "Allah eliminó el sufrimiento de Ayyub (AS)."),
        "dua_husn_khatimah" to DuaText("Morir como musulmán (Yusuf AS)", "Creador de los cielos y de la tierra, Tú eres mi Protector en este mundo y en el Más Allá. Hazme morir como musulmán y únete a mí con los justos.", "Un dua para un buen final.", "La dua del profeta Yusuf (AS)."),
        "dua_shaitan_hamazat" to DuaText("Refugio de los susurros del diablo", "Señor mío, en Ti me refugio de los susurros de los demonios, y en Ti me refugio, mi Señor, para que no se acerquen a mí.", "Refugio de los susurros satánicos.", "Una dua coránica de búsqueda de refugio."),
        "dua_bad_character" to DuaText("Refugio del mal carácter", "Oh Allah, busco refugio en Ti del mal carácter, las malas acciones y los malos deseos.", "Refugio del mal carácter, hechos y deseos.", "Un dua de refugio del Profeta ﷺ."),
        "dua_zawal_nimah" to DuaText("Refugio de la pérdida de bendiciones", "Oh Allah, busco refugio en Ti de la pérdida de Tus bendiciones, del cambio del bienestar que has dado, de Tu castigo repentino y de todo Tu disgusto.", "Refugio de perder bendiciones y de calamidades repentinas.", "Un dua del Profeta ﷺ."),
        "dua_useless_knowledge" to DuaText("Refugio del conocimiento no beneficioso", "Oh Allah, busco refugio en Ti del conocimiento que no beneficia, de un corazón que no teme, de un alma que nunca está satisfecha y de una dua que no recibe respuesta.", "Refugio del conocimiento inútil y de un corazón sin temor a Allah.", "Un dua de refugio del Profeta ﷺ."),
        "dua_beneficial_knowledge" to DuaText("Conocimiento beneficioso y Halal Rizq", "Oh Allah, te pido conocimiento beneficioso, provisión pura y obras aceptadas.", "Después de la oración del Fajr.", "El Profeta ﷺ dijo esto después del salam del Fajr."),
        "dua_leprosy_diseases" to DuaText("Refugio de enfermedades graves", "Oh Allah, busco refugio en Ti contra el vitíligo, la locura, la lepra y todas las enfermedades malignas.", "Protección contra enfermedades graves.", "Una Sunnah dua para preservar la salud."),
        "dua_fear_people" to DuaText("Miedo a los enemigos o a los opresores", "Oh Allah, te colocamos ante ellos y buscamos refugio en Ti de su maldad.", "Al temer el daño de un pueblo o de una persona.", "El Profeta ﷺ dijo esto cuando temía a un pueblo."),
        "dua_shirk_protection" to DuaText("Protección contra el shirk oculto", "Oh Allah, busco refugio en Ti para no asociar nada contigo a sabiendas, y busco Tu perdón por lo que hago sin saberlo.", "Para mantenerse a salvo de alardear y eludir eludir cosas ocultas.", "El shirk oculto es más oculto que el arrastrarse de una hormiga."),
        "dua_rain" to DuaText("cuando llueve", "Oh Allah, (envía) una lluvia beneficiosa.", "Cuando llueve.", "La lluvia es un momento en el que se aceptan duas."),
        "dua_after_rain" to DuaText("Después de la lluvia", "Hemos recibido lluvia por la generosidad de Allah y Su misericordia.", "Después de la lluvia.", "Quien dice esto es un creyente en Allah."),
        "dua_istisqa" to DuaText("Pidiendo lluvia (Istisqa)", "Oh Allah, envíanos lluvia (tres veces).", "Cuando no llueve.", "El Profeta ﷺ hizo esta dua en el sermón del viernes y llovió."),
        "dua_heavy_rain" to DuaText("Lluvia excesiva", "Oh Allah, (déjalo caer) a nuestro alrededor y no sobre nosotros.", "Cuando llueve demasiado.", "Las nubes se alejaron a través del dua del Profeta ﷺ."),
        "dua_wind" to DuaText("Cuando sopla el viento", "Oh Allah, te pido por su bien, el bien que hay en él y el bien con el que fue enviado, y busco refugio en Ti de su mal, el mal que hay en él y el mal con el que fue enviado.", "Cuando sopla un fuerte viento o tormenta.", "El Profeta ﷺ hizo esta dua durante las tormentas."),
        "dua_thunder" to DuaText("Escuchar truenos", "Gloria a Aquel a quien el trueno glorifica con su alabanza, y los ángeles por temor a él.", "Al oír el trueno: la práctica de Abdullah ibn az-Zubayr (RA).", "Tomado de Surah ar-Ra'd (13:13)."),
        "dua_new_moon" to DuaText("Ver la luna nueva", "Oh Allah, deja que esta luna salga sobre nosotros con bendición, fe, seguridad e Islam. (Oh luna), mi Señor y vuestro Señor es Allah.", "Al ver la luna nueva.", "La Sunnah dua para cada nuevo mes."),
        "dua_janaza_adult" to DuaText("Oración de Janaza (Adulto)", "Oh Allah, perdona a nuestros vivos y a nuestros muertos, a los presentes y a los ausentes, a nuestros jóvenes y a nuestros viejos, a nuestros hombres y a nuestras mujeres. Oh Allah, a quien de nosotros mantengas con vida, mantenlo vivo en el Islam, y a quien de nosotros hagas morir, haz que muera por la fe.", "Después del tercer takbir de la oración fúnebre.", "La Sunnah dua para un adulto fallecido."),
        "dua_janaza_child" to DuaText("Oración de Janaza (Niño)", "Oh Allah, haz de él un precursor (y anfitrión) para nosotros, haz de él una recompensa y un tesoro para nosotros, y haz de él un intercesor para nosotros cuya intercesión sea aceptada.", "En la oración fúnebre de un niño (para una niña, diga 'ij'alhā').", "La Sunnah dua practicada por los Hanafis."),
        "dua_mayyit_awf" to DuaText("Dua detallada para los difuntos", "Oh Allah, perdónalo, ten piedad de él, dale bienestar y perdónalo. Haz que su recepción sea honrosa y su tumba espaciosa, lávalo con agua, nieve y granizo, y límpialo de pecados como se limpia un vestido blanco de la suciedad.", "En la oración fúnebre o por el difunto.", "Awf ibn Malik (RA) deseó haber sido esa persona fallecida."),
        "dua_visiting_graves" to DuaText("Visitando las tumbas", "La paz sea con vosotros, oh creyentes y musulmanes habitantes de estos hogares. Nosotros también, si Allah quiere, nos uniremos a vosotros. Pido a Allah por el bienestar para nosotros y para vosotros.", "Al entrar al cementerio.", "Visitar las tumbas recuerda la muerte y el Más Allá."),
        "dua_closing_eyes" to DuaText("Al cerrar los ojos del difunto", "Oh Allah, perdona a (nombre), eleva su rango entre los guiados, sé su sucesor entre aquellos que deja atrás. Perdónanos a nosotros y a él, oh Señor de los mundos; haz espaciosa su tumba y llénala de luz.", "Al cerrar los ojos del difunto (mencionando su nombre).", "El Profeta ﷺ hizo esta dua para Abu Salamah (RA)."),
        "dua_condolence" to DuaText("Condolencia (Ta'ziyah)", "Ciertamente a Allah pertenece lo que tomó y a Él pertenece lo que dio, y todo en Él tiene un plazo determinado, así que sed pacientes y esperad la recompensa.", "Ofreciendo condolencias a una familia después de una muerte.", "El Profeta ﷺ envió este mensaje a su hija."),
        "dua_placing_in_grave" to DuaText("Colocar al difunto en la tumba", "En el nombre de Allah y siguiendo el camino del Mensajero de Allah ﷺ.", "Al bajar al difunto a la tumba.", "La Sunnah dua del entierro."),
        "dua_sneezing" to DuaText("Estornudos", "Toda alabanza es para Allah. — Que Allah tenga piedad de vosotros. — Que Allah os guíe y arregle vuestros asuntos.", "Al estornudar; el oyente dice 'Yarhamukallah', luego el que estornudó responde.", "Es uno de los derechos de un musulmán sobre otro musulmán."),
        "dua_toilet_enter" to DuaText("Entrar al baño", "En nombre de Alá. Oh Allah, busco refugio en Ti de los genios impuros masculinos y femeninos.", "Antes de entrar al baño con el pie izquierdo.", "Bismillah se convierte en una pantalla entre los genios y la persona."),
        "dua_toilet_exit" to DuaText("Salir del baño", "(Oh Allah), busco Tu perdón.", "Al salir del baño con el pie derecho.", "El Profeta ﷺ dijo esto al salir del baño."),
        "dua_thanking" to DuaText("Agradeciendo a alguien", "Que Allah os recompense con el bien.", "Cuando alguien te hace un favor.", "Quien dice esto ha expresado plenamente su agradecimiento."),
        "dua_love_for_allah" to DuaText("Cuando alguien dice 'Te amo por Allah'", "Que Él (Allah), por quien me amáis, os ame.", "Cuando alguien dice \"te amo por el amor de Alá\".", "La Sunnah responde al amor por el amor de Allah."),
        "dua_seeing_muslim_smile" to DuaText("Saludo (Salam)", "La paz sea con vosotros y la misericordia de Allah y Sus bendiciones.", "Al encontrarse con un musulmán.", "Decir el salam completo genera treinta buenas acciones."),
        "dua_dressing" to DuaText("Vestirse", "Toda alabanza es para Allah quien me vistió con esto y me lo proporcionó sin ninguna fuerza o poder de mi parte.", "Al vestirse.", "Buenas nuevas de perdón de pecados pasados."),
        "dua_rooster_donkey" to DuaText("Escuchar un gallo o un burro", "Oh Allah, te pido tu generosidad (gallo). — Busco refugio en Allah de Shaytan, el maldito (asno).", "Al oír a un gallo pedir la generosidad de Allah; on hearing a donkey bray seek refuge from Shaytan.", "El gallo ve un ángel y el burro ve un diablo."),
        "dua_something_liked" to DuaText("Ver algo admirable (contra el mal de ojo)", "Lo que Allah ha querido. Oh Allah, que lo bendiga.", "Al ver algo admirable perteneciente a alguien, ore por bendición.", "Orar por la bendición previene el mal de ojo."),
        "dua_sell_buy_debt_repaid" to DuaText("Al pagar una deuda", "Que Allah te bendiga en tu familia y en tu riqueza.", "Para el prestamista a la hora de pagar una deuda.", "El retorno de un préstamo es agradecimiento y reembolso."),
        "dua_talbiyah" to DuaText("Talbiyá", "Aquí estoy, oh Allah, aquí estoy. Aquí estoy, no tienes pareja, aquí estoy. Seguramente toda alabanza, bendiciones y dominio son tuyos. No tienes pareja.", "En voz alta después de entrar al ihram.", "El emblema del Hajj y la Umrah."),
    )
}
